  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Acalabrutinib had an absolute bioavailability of 25.3% in healthy subjects by oral/intravenous AUC comparison, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Asciminib was predicted to be almost completely absorbed with an absolute bioavailability of ~73% in humans, a strong high-F anchor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Maraviroc showed 33% oral bioavailability in healthy subjects after a 300 mg oral dose compared with i.v. dosing, above the 20% threshold despite P-gp-related nonlinearity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Pradigastat was judged completely bioavailable after oral dosing in healthy subjects by comparison with an intravenous dose, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Delavirdine had an oral bioavailability of 85% in patients with HIV infection, providing a high-F example with a heteroaromatic/piperazine scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20% (mostly 25–90%), with no affirmative low-F evidence; therefore the query is predicted high for the F ≥20% threshold.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "No exact structural analogue with the same pyrrole-biphenyl-pyrrole dimeric scaffold in the evidence set.",
    "Solubility, permeability, and first-pass metabolism data for the query are absent.",
    "Encainide shows wide interindividual bioavailability variability, but its mean remains above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

